<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\LoadService;use App\Support\Url;Auth::requirePermission('LOAD_VIEW_OWN');$loads=LoadService::all();$pageTitle='My Loads';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>My Loads</h1><p>Company-scoped freight requests.</p></div><a class="button" href="<?=h(Url::to('loads/create.php'))?>">Post a Load</a></div><div class="card table-wrap"><table><thead><tr><th>Reference</th><th>Cargo</th><th>Route</th><th>Pickup</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($loads as$l):?><tr><td><?=h($l['load_ref'])?></td><td><?=h($l['cargo_summary'])?></td><td><?=h(($l['origin_city']?:'—').' → '.($l['destination_city']?:'—'))?></td><td><?=h($l['requested_pickup_from']?:'Not set')?></td><td><span class="status-pill"><?=h($l['current_status'])?></span></td><td><a href="<?=h(Url::to('loads/view.php?id='.$l['load_id']))?>">View</a></td></tr><?php endforeach;if(!$loads):?><tr><td colspan="6" class="muted">No loads have been created.</td></tr><?php endif;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';
